import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int h = scanner.nextInt();

        int[][] dpTable = new int[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                dpTable[i][j] = -1;
            }
        }
        dpTable[0][0] = 1;

        System.out.println(compute(n, h, dpTable));
        scanner.close();
    }

    private static int compute(int n, int h, int[][] dpTable) {
        if (dpTable[n][h] != -1) {
            return dpTable[n][h];
        }
        if (n == 0) {
            return 0;
        }
        if (h == 0) {
            return compute(n, 1, dpTable);
        }

        int total = 0;
        for (int i = 0; i < n; i++) {
            total += compute(n - i - 1, 0, dpTable) * compute(i, h - 1, dpTable);
            total += compute(n - i - 1, h - 1, dpTable) * compute(i, 0, dpTable);
            total -= compute(n - i - 1, h - 1, dpTable) * compute(i, h - 1, dpTable);
        }

        dpTable[n][h] = total;
        return total;
    }
}
